import org.apache.commons.lang3.time.*;
import java.util.*;
public class TestJP {
    public static void main(String[] args) throws Exception {
        TimeZone gmt = TimeZone.getTimeZone("GMT");
        Locale jp = new Locale("ja","JP","JP");
        java.lang.reflect.Constructor<FastDateParser> c = FastDateParser.class.getDeclaredConstructor(String.class, TimeZone.class, Locale.class);
        c.setAccessible(true);
        FastDateParser p = c.newInstance("yyyy-MM-dd", gmt, jp);
        try {
            Date d = p.parse("1000-01-01");
            System.out.println("parsed: " + d);
        } catch (Exception e) {
            System.out.println("exception: " + e);
        }
    }
}
EOF
